# Verify: triangle-free and maximal
edges = [(0, 2), (0, 18), (0, 19), (1, 2), (1, 18), (1, 19), (2, 3), (2, 4), (2, 5), (2, 6), (2, 7), (2, 8), (2, 9), (2, 10), (2, 11), (2, 12), (2, 13), (2, 14), (2, 15), (2, 16), (2, 17), (3, 18), (3, 19), (4, 18), (4, 19), (5, 18), (5, 19), (6, 18), (6, 19), (7, 18), (7, 19), (8, 18), (8, 19), (9, 18), (9, 19), (10, 18), (10, 19), (11, 18), (11, 19), (12, 18), (12, 19), (13, 18), (13, 19), (14, 18), (14, 19), (15, 18), (15, 19), (16, 18), (16, 19), (17, 18), (17, 19)]
n=20
adj=[[False]*n for _ in range(n)]
for u,v in edges:
    adj[u][v]=adj[v][u]=True
# triangle free
for a in range(n):
    for b in range(a+1,n):
        for c in range(b+1,n):
            if adj[a][b] and adj[a][c] and adj[b][c]:
                print("triangle",a,b,c)
# maximal
for u in range(n):
    for v in range(u+1,n):
        if not adj[u][v]:
            # adding shouldn't be triangle-free -> must have common neighbor
            ok=False
            for w in range(n):
                if w!=u and w!=v and adj[u][w] and adj[v][w]:
                    ok=True;break
            if not ok:
                print("not maximal",u,v)
print("done")
# fixed
for e in [(1,18),(4,18),(16,18),(4,19),(17,18),(11,19),(3,19)]:
    assert e in edges
print("fixed ok")
